def skjkasdkd(lst):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    max_prime = 0
    for num in lst:
        if is_prime(abs(num)) and num > max_prime:
            max_prime = num

    return sum(int(digit) for digit in str(max_prime) if digit != '0') if max_prime else 0
